import { LightConfig } from "type";
import { gameConfig } from "game/config";
import { GameScene } from "../GameScene";

export class Light {
  constructor(scene: GameScene, config: LightConfig) {
    const {
      x,
      y,
      color = gameConfig.colors.defaultLight,
      intensity = 1.5,
      radius = 300,
      id,
      positionType,
    } = config;

    let xCoordinate = x,
      yCoordinate = y;

    debugger;

    if (positionType === "tile") {
      console.log("tilemap", scene.tilemap);

      const ground = scene.tilemap?.getTilesWithinWorldXY(
        x,
        y,
        scene.tilemap.width,
        scene.tilemap.height,
        {},
        scene.camera,
        // "ground",
      );
      console.log(ground);

      if (ground) {
        // xCoordinate = ground.x;
        // yCoordinate = ground.y;
      }
    }

    this.light = scene.lights
      .addLight(xCoordinate, yCoordinate, radius, color)
      .setIntensity(intensity);

    this.id = id;
  }

  light: Phaser.GameObjects.Light;
  id?: string;
}
